import pandas as pd

def clean(df):
    df = df.copy()
    # Standardize Region label variants and whitespace
    if 'Region' in df.columns:
        def norm_region(v):
            if pd.isna(v):
                return v
            if not isinstance(v, str):
                v = str(v)
            s = v.strip().lower()
            mapping = {'north': 'North', 'south': 'South', 'east': 'East', 'west': 'West'}
            return mapping.get(s, v.strip().title())
        df['Region'] = df['Region'].apply(norm_region)
    # Fix Quantity: must be positive whole number
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
        # correct sign errors by taking absolute value
        df['Quantity'] = df['Quantity'].abs()
        # ensure integer
        df['Quantity'] = df['Quantity'].round().astype('Int64')
    # Recompute Revenue to enforce Revenue = Quantity * Price
    if 'Quantity' in df.columns and 'Price' in df.columns:
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
        df['Revenue'] = df['Quantity'] * df['Price']
    # Keep Order_ID as identifier
    return df

def answer(df):
    # total revenue by Category on cleaned data
    if 'Category' not in df.columns or 'Revenue' not in df.columns:
        return {}
    grouped = df.groupby('Category', dropna=False)['Revenue'].sum()
    # drop missing group keys
    result = {str(k): float(v) for k, v in grouped.items() if pd.notna(k)}
    return result
